import (
	stdout from "@std/io/io.ms",
	arguments from "@std/os/env.ms",
)

fn show(number: Int) Result[Unit, Error]:
	try stdout().write("{number}\n")
	return stdout().flush()

export fn main() Int:
	number := arguments().get(0, default: "42").parse_int()
	if value := number:
		if show(value).is_ok(): return 0
	return 1
